const $=s=>document.querySelector(s);const money=n=>'Rp '+n.toLocaleString('id-ID');
const games=[
{id:'gatot',name:'Legenda Gatotkaca',island:'Jawa',genre:'Aksi',tags:'Mitologi · Aksi RPG',price:149000,art:-1,desc:'Terbang melampaui legenda. Jelajahi tanah Jawa dan temukan kekuatan sang kesatria.',note:'Petualangan fantasi yang terinspirasi tokoh pewayangan. Cerita mitologi, bukan catatan peristiwa sejarah.'},
{id:'malin',name:'Malin Kundang',island:'Sumatra',genre:'Petualangan',tags:'Cerita rakyat · Petualangan',price:39000,old:99000,art:0,desc:'Berlayar ke pesisir Sumatra dalam kisah tentang keluarga, pilihan, dan arti pulang.',note:'Terinspirasi cerita rakyat Malin Kundang dari Sumatra Barat.'},
{id:'roro',name:'Roro Jonggrang',island:'Jawa',genre:'Puzzle',tags:'Mitologi · Puzzle',price:77000,old:129000,art:1,desc:'Pecahkan teka-teki seribu candi di bawah langit malam Jawa.',note:'Mengangkat legenda Roro Jonggrang. Legenda ini berbeda dari sejarah pembangunan kompleks Prambanan.'},
{id:'pitung',name:'Si Pitung',island:'Jawa',genre:'Aksi',tags:'Cerita Betawi · Aksi',price:66000,old:89000,art:2,desc:'Susuri kampung Betawi dan bantu warga bersama jagoan yang pemberani.',note:'Adaptasi kreatif kisah Si Pitung dalam tradisi masyarakat Betawi.'},
{id:'timun',name:'Timun Mas',island:'Jawa',genre:'Petualangan',tags:'Cerita rakyat · Petualangan',price:39000,old:79000,art:3,desc:'Bekal ajaib, hutan penuh rahasia, dan keberanian seorang gadis kecil.',note:'Petualangan terinspirasi dongeng Timun Mas, dengan pesan keberanian dan kecerdikan.'},
{id:'sangkuriang',name:'Sangkuriang',island:'Jawa',genre:'Puzzle',tags:'Cerita Sunda · Puzzle',price:48000,old:69000,art:5,desc:'Jelajahi hutan, danau, dan teka-teki dalam kisah legendaris dari tanah Sunda.',note:'Terinspirasi legenda asal-usul Tangkuban Perahu, bukan penjelasan geologis terbentuknya gunung.'},
{id:'majapahit',name:'Ksatria Majapahit',island:'Jawa',genre:'Strategi',tags:'Inspirasi sejarah · Strategi',price:89000,art:4,desc:'Masuki dunia kerajaan, bangun strategi, dan kenali warisan Majapahit.',note:'Konsep fiksi berlatar inspirasi Majapahit. Tokoh dan misi dirancang untuk permainan.'}];
const features=['gatot','sangkuriang','majapahit','timun'];const islandNames=['Sumatra','Jawa','Kalimantan','Sulawesi','Bali & Nusa Tenggara','Maluku & Papua'];
let selected=0,island='',genre='Semua',query='';
const artStyle=n=>n===-1?'background-image:url(assets/hero.webp);background-size:cover;background-position:70% center':`background-position:${n%3*50}% ${Math.floor(n/3)*100}%`;
function selectFeature(i){selected=i;const g=games.find(g=>g.id===features[i]);$('#heroScene').classList.toggle('hero-original',g.art===-1);$('#herotitle').innerHTML=g.name.replace(' ','<br>');$('#herotype').textContent=g.tags.toUpperCase();$('#herodesc').textContent=g.desc;$('#heroScene').style.backgroundImage=`linear-gradient(90deg,rgba(9,41,30,.66),rgba(9,41,30,.13) 58%,rgba(9,41,30,0)),url('assets/${g.art===-1?'hero':'games'}.webp')`;$('#heroScene').style.backgroundSize=g.art===-1?'cover':'auto,300% 200%';$('#heroScene').style.backgroundPosition=g.art===-1?'center':`center,${g.art%3*50}% ${Math.floor(g.art/3)*100}%`;$('#featurelist').innerHTML=features.map((id,n)=>{const f=games.find(x=>x.id===id);return `<button class="feature-item ${n===selected?'selected':''}" data-feature="${n}" aria-pressed="${n===selected}"><span class="thumb ${f.art===-1?'hero-thumb':''}" style="${artStyle(f.art)}"></span><span><strong>${f.name}</strong><small>${f.genre}${id==='gatot'?' · RPG':''}</small></span></button>`}).join('');$('#dots').innerHTML=features.map((x,i)=>`<button data-feature="${i}" class="${i===selected?'selected':''}" aria-label="Game unggulan ${i+1}" aria-pressed="${i===selected}"></button>`).join('')}
const islandMap=[{x:4,y:7,w:16},{x:20,y:50,w:14},{x:28,y:3,w:15},{x:51,y:9,w:13},{x:44,y:58,w:12},{x:72,y:18,w:18}];
const off=g=>g.old?Math.round((1-g.price/g.old)*100):0;
const heartBtn=(g,cls='save-game')=>`<button type="button" class="${cls}" aria-label="Wishlist ${g.name}">♡</button>`;
function islandsMap(){return `<div class="map-scroll"><div class="map-board"><svg class="map-route" viewBox="0 0 1200 500" preserveAspectRatio="none" aria-hidden="true"><path d="M144 131C230 110 330 70 426 105S350 260 324 334 520 400 600 362 650 170 690 123 900 130 972 198"/></svg><span class="map-sea" style="left:3%;top:70%">Samudra Hindia</span><span class="map-sea" style="left:35.5%;top:55%">Laut Jawa</span><span class="map-sea" style="left:63%;top:86%">Laut Banda</span><svg class="map-compass" viewBox="0 0 60 60" aria-hidden="true"><circle cx="30" cy="30" r="27"/><path d="M30 6l6 24-6 24-6-24z"/><path d="M30 6l6 24h-12z" class="n"/><text x="30" y="5">U</text></svg><span class="map-legend">✦ Pilih pulau untuk menyaring game</span>${islandNames.map((x,i)=>{const p=islandMap[i],n=games.filter(g=>g.island===x).length;return `<button class="isle ${island===x?'selected':''} ${n?'':'soon'}" data-island="${x}" aria-pressed="${island===x}" style="left:${p.x}%;top:${p.y}%;width:${p.w}%;--i:${i}"><span class="isle-art" style="background-position:${i%3*50}% ${Math.floor(i/3)*100}%"></span><span class="isle-tag"><strong>${x}</strong><small>${n?n+' game':'Segera hadir'}</small></span>${island===x?'<span class="isle-pin">✦ Kamu di sini</span>':''}</button>`}).join('')}</div></div><p class="map-hint" aria-hidden="true">← Geser peta →</p>`}
function deals(list){if(!list.length)return '';const [top,...rest]=[...list].sort((a,b)=>off(b)-off(a));return `<div class="deals ${rest.length?'':'solo'}"><article class="deal-spot"><button type="button" class="deal-cover" style="${artStyle(top.art)}" aria-label="Lihat ${top.name}"></button><span class="deal-burst" aria-hidden="true"><small>HEMAT</small>${off(top)}%</span><div class="deal-body"><span class="deal-kicker">✦ DISKON TERBESAR</span><h3><a href="#" onclick="return false">${top.name}</a></h3><p class="deal-tags">${top.island} · ${top.genre}</p><p class="deal-desc">${top.desc}</p><div class="deal-price"><del>${money(top.old)}</del><strong>${money(top.price)}</strong><span>Kamu hemat ${money(top.old-top.price)}</span></div><div class="deal-actions"><button type="button" class="btn">Lihat cerita <span>↗</span></button>${heartBtn(top,'deal-wish')}</div></div></article>${rest.length?`<div class="coupons"><span class="coupons-label">KUPON LAINNYA · ${rest.length}</span>${rest.map(g=>`<article class="coupon"><button type="button" class="coupon-thumb" style="${artStyle(g.art)}" aria-label="Lihat ${g.name}"></button><div class="coupon-info"><h3><a href="#" onclick="return false">${g.name}</a></h3><p>${g.island} · ${g.genre}</p><div class="price"><del>${money(g.old)}</del>${money(g.price)}</div></div><div class="coupon-stub"><strong>−${off(g)}%</strong>${heartBtn(g)}</div></article>`).join('')}</div>`:''}</div>`}
function ranks(list){if(!list.length)return '';return `<ol class="ranks">${list.map((g,i)=>`<li class="rank"><span class="rank-num" aria-hidden="true">${i+1}</span><div class="rank-card"><button type="button" class="rank-cover" style="${artStyle(g.art)}" aria-label="Lihat ${g.name}">${i===0?'<span class="rank-crown">♛ NOMOR SATU</span>':''}${g.old?`<span class="discount">−${off(g)}%</span>`:''}</button><div class="rank-info"><h3><a href="#" onclick="return false">${g.name}</a></h3><p>${g.island} · ${g.genre}</p><div class="price">${g.old?`<del>${money(g.old)}</del>`:''}${money(g.price)}</div>${heartBtn(g)}</div></div></li>`).join('')}</ol>`}
function match(g){return (!island||g.island===island)&&(genre==='Semua'||g.genre===genre||(genre==='Mitologi'&&g.tags.includes('Mitologi')))&&(!query||(g.name+' '+g.tags+' '+g.island).toLowerCase().includes(query))}
function render(){selectFeature(selected);$('#islands').innerHTML=islandsMap();$('#genres').innerHTML=['Semua','Mitologi','Aksi','Strategi','Petualangan','Puzzle'].map(x=>`<button class="chip ${genre===x?'selected':''}" data-genre="${x}" aria-pressed="${genre===x}">${x}</button>`).join('');const empty='<div class="empty">Belum ada game untuk pilihan ini. Coba pulau atau genre lainnya.</div>';$('#promocards').innerHTML=deals(games.filter(g=>g.old&&match(g)))||empty;$('#popularcards').innerHTML=ranks(['majapahit','sangkuriang','timun','gatot','roro'].map(id=>games.find(g=>g.id===id)).filter(match))||empty;const filtered=!!(island||query||genre!=='Semua');$('#resultNote').hidden=!filtered;$('#resultNote').textContent=`${games.filter(match).length} game ditemukan${island?' · '+island:''}${genre!=='Semua'?' · '+genre:''}${query?' · pencarian “'+query+'”':''}`}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.feature!==undefined)selectFeature(+d.feature);if(d.island){island=island===d.island?'':d.island;render()}if(d.genre){genre=d.genre;render()}if(d.all){island='';genre='Semua';query='';$('#search').value='';render();$('#'+d.all).scrollIntoView({behavior:'smooth'})}});
$('#search').oninput=e=>{query=e.target.value.trim().toLowerCase();render()};$('#resetIsland').onclick=()=>{island='';genre='Semua';query='';$('#search').value='';render()};$('#menu').onclick=()=>{const open=$('#navlinks').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('#navlinks').onclick=e=>{if(e.target.closest('a,button'))$('#navlinks').classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});render();
